  function toast(message){clearTimeout(state.toastTimeout);$('#toast').textContent=message;$('#toast').hidden=false;state.toastTimeout=setTimeout(()=>$('#toast').hidden=true,2600);}
  function openDialog(id){const dialog=$('#'+id);state.returnFocus.set(id,document.activeElement);if(!dialog.open)dialog.showModal();if(id==='nav-drawer')$('#nav-trigger').setAttribute('aria-expanded','true');}
  function closeDialog(id,force=false){const dialog=$('#'+id);if(!dialog.open)return true;if(id==='detail-sheet'&&state.newFormDirty&&!force){confirmation('保留新建内容？','名称和说明尚未保存。可以继续编辑、放弃，或创建后关闭。',[{label:'继续编辑',run:()=>{}},{label:'放弃',kind:'danger',run:()=>{state.newFormDirty=false;state.newForm=null;closeDialog(id,true);}},{label:'创建',kind:'primary',run:()=>saveNew(state.newForm)}]);return false;}dialog.close();if(id==='nav-drawer')$('#nav-trigger').setAttribute('aria-expanded','false');const trigger=state.returnFocus.get(id);if(trigger?.isConnected)trigger.focus();else content.focus();return true;}
  function confirmation(title,message,choices){$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-actions').innerHTML=choices.map((choice,index)=>`<button class="button ${choice.kind||'secondary'}" data-confirm="${index}">${escape(choice.label)}</button>`).join('');state.onConfirm=choices;openDialog('confirm-dialog');}
