  function taskRow(task){return `<li class="task-row ${task.done?'is-done':''}" data-task="${task.id}"><button class="check-button" data-action="toggle-task" data-id="${task.id}" aria-pressed="${task.done}" aria-label="${task.done?'标为未完成':'完成'}：${escape(task.title)}"><span class="check-mark">${task.done?icon('check'):''}</span></button><button class="task-copy" data-action="task-detail" data-id="${task.id}"><strong>${escape(task.title)}</strong><small>${escape(task.project)}${task.parentId?' · '+escape(taskTitle(task.parentId)):''}</small></button><button class="icon-button" data-action="task-menu" data-id="${task.id}" aria-label="更多任务操作">${icon('more')}</button></li>`;}
  function homePage(){const labels=['重要且紧急','重要不紧急','紧急不重要','不紧急不重要'];return `<p class="eyebrow">今天 / 11月28日 星期六 · 演示</p><p class="intro">把注意力放在真正需要推进的事上。</p><button class="button primary full" data-action="new-task">${icon('plus')}新建任务</button>${labels.map((label,index)=>`<div class="section-heading"><h2 class="quadrant-title ${index?'plan':''}">${label}</h2><span class="muted">${tasks.filter(t=>t.quadrant===index+1&&!t.done).length} 项</span></div><ul class="task-list">${tasks.filter(t=>t.quadrant===index+1&&!t.done).slice(0,3).map(taskRow).join('')||'<li class="helper">当前没有待办任务。</li>'}</ul>`).join('')}<p class="helper">本页拖动与更多操作以原任务语义为准；原型只演示内存状态。</p>`;}
  function dashboardPage(){return `<p class="eyebrow">今天 / 工作台</p><h2 class="lead">先完成当前这一步。</h2><p class="intro">3 项工作正在推进，下一步已经明确。</p><section class="next-work"><div class="work-trail"><p class="eyebrow">MYTODO 交互改版 / 下一步</p><h3>核对番茄钟的全部操作与记录</h3><p>进行中 · 林青 · 预计 25 分钟</p></div><div class="button-row"><button class="button primary" data-action="focus-task" data-id="timer-review">${icon('play')}开始专注</button><button class="button secondary" data-action="work-detail" data-id="w1">查看事项</button></div></section><div class="tiny-stats"><div><strong>3</strong><span>进行中事项</span></div><div><strong>2</strong><span>待跟进</span></div><div><strong>38.7</strong><span>今日专注 / 分钟</span></div></div><div class="section-heading"><h2>接下来</h2><button class="text-button" data-route="work">全部事项</button></div>${workItems.slice(1).map(workCard).join('')}<div class="section-heading"><h2>工作脉络</h2><button class="text-button" data-route="instances">流程实例</button></div><div class="work-trail"><h3>界面审阅流程</h3><p>原始需求 → 现状审计 → <b>交互设计</b> → 平台候选</p></div>`;}
  function tasksPage(){let list=tasks.filter(t=>!state.taskQuery||t.title.toLowerCase().includes(state.taskQuery.toLowerCase()));if(state.taskFilter==='open')list=list.filter(t=>!t.done);if(state.taskFilter==='done')list=list.filter(t=>t.done);return `<label for="list-search">查找任务</label><div class="search-field">${icon('search')}<input id="list-search" type="search" placeholder="输入任务关键词" value="${escape(state.taskQuery)}"></div><div class="filter-tabs" role="tablist" aria-label="任务筛选">${[['all','全部'],['open','未完成'],['done','已完成']].map(([id,label])=>`<button role="tab" data-action="task-filter" data-value="${id}" aria-selected="${state.taskFilter===id}">${label}</button>`).join('')}</div><div id="task-list-results"><ul class="task-list">${list.map(taskRow).join('')}</ul>${!list.length?empty('没有匹配任务','换个关键词，或新建一项任务。'):''}</div><div class="form-footer"><button class="button primary full" data-action="new-task">${icon('plus')}新建任务</button></div>`;}
